def execute_command(command, timeout_ms=None, **_extra):
    import json, os, datetime, time, subprocess, random, signal

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32]); ts //= 32
        for _ in range(16):
            out.append(alphabet[random.randrange(32)])
        return prefix + "".join(reversed(out))

    def _normalize_cmd(s):
        return " ".join(str(s).strip().split())

    def _pick_workspace_for_command():
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
        if not candidates:
            candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") in ("active", "suspended")]
        for w in candidates:
            dct = w.get("default_command_timeout_ms")
            mct = w.get("max_command_timeout_ms")
            allowed = w.get("allowed_directories")
            if isinstance(dct, (int, float)) and not isinstance(dct, bool) and dct >= 1 and isinstance(mct, (int, float)) and not isinstance(mct, bool) and mct >= dct and isinstance(allowed, list) and len(allowed) >= 1 and isinstance(w.get("id"), str) and w.get("id"):
                return w
        return None

    t0 = time.time()
    started_at = _now()

    if not isinstance(command, str):
        return _err("VALIDATION_ERROR", "command must be a string.", field="command")
    norm_cmd = _normalize_cmd(command)
    if not norm_cmd:
        return _err("VALIDATION_ERROR", "command must be a non-empty string.", field="command")

    if timeout_ms is not None and (not isinstance(timeout_ms, (int, float)) or isinstance(timeout_ms, bool)):
        return _err("VALIDATION_ERROR", "timeout_ms must be a number when provided.", field="timeout_ms")

    ws = _pick_workspace_for_command()
    if not ws:
        return _err("UNAUTHORIZED", "No workspace context available for this request.")

    if timeout_ms is None:
        timeout_ms = ws.get("default_command_timeout_ms")
    try:
        timeout_ms = float(timeout_ms)
    except Exception:
        return _err("VALIDATION_ERROR", "timeout_ms must be a number.", field="timeout_ms")
    if timeout_ms < 1:
        return _err("VALIDATION_ERROR", "timeout_ms must be >= 1.", field="timeout_ms")

    max_timeout = ws.get("max_command_timeout_ms")
    if not isinstance(max_timeout, (int, float)) or isinstance(max_timeout, bool) or float(max_timeout) < 1:
        return _err("CONFLICT", "Workspace policy is invalid for max_command_timeout_ms.", workspace_id=ws.get("id"))
    if timeout_ms > float(max_timeout):
        # record denial as a failed session (allowed by business rules)
        sessions = _load("terminal_sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        now = _now()
        row = {
            "id": _new_id("dcm_tses_"),
            "workspace_id": ws.get("id"),
            "os_pid": 0,
            "command": norm_cmd,
            "timeout_ms": float(timeout_ms),
            "cwd": None,
            "status": "failed",
            "exit_code": None,
            "started_at": now,
            "ended_at": now,
            "last_output_offset": 0,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(row)
        _save("terminal_sessions.json", sessions)
        return _err(
            "CONFLICT",
            "timeout_ms exceeds workspace.max_command_timeout_ms; request denied by workspace policy.",
            workspace_id=ws.get("id"),
            timeout_ms=float(timeout_ms),
            max_command_timeout_ms=float(max_timeout),
            session=row,
        )

    # Blocklist check
    blocked = _load("blocked_commands.json")
    if not isinstance(blocked, list):
        blocked = []
    is_blocked = False
    for b in blocked:
        if not isinstance(b, dict):
            continue
        if b.get("workspace_id") == ws.get("id") and b.get("status") == "blocked" and _normalize_cmd(b.get("command", "")) == norm_cmd:
            is_blocked = True
            break

    if is_blocked:
        sessions = _load("terminal_sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        now = _now()
        row = {
            "id": _new_id("dcm_tses_"),
            "workspace_id": ws.get("id"),
            "os_pid": 0,
            "command": norm_cmd,
            "timeout_ms": float(timeout_ms),
            "cwd": None,
            "status": "failed",
            "exit_code": None,
            "started_at": now,
            "ended_at": now,
            "last_output_offset": 0,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(row)
        _save("terminal_sessions.json", sessions)
        return _err(
            "CONFLICT",
            "Command is blocked for this workspace by blocked_commands policy.",
            workspace_id=ws.get("id"),
            command=norm_cmd,
            session=row,
        )

    # Execute
    sessions = _load("terminal_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    outputs = _load("terminal_output_chunks.json")
    if not isinstance(outputs, list):
        outputs = []

    now = _now()
    session_row = {
        "id": _new_id("dcm_tses_"),
        "workspace_id": ws.get("id"),
        "os_pid": 0,
        "command": norm_cmd,
        "timeout_ms": float(timeout_ms),
        "cwd": None,
        "status": "starting",
        "exit_code": None,
        "started_at": now,
        "ended_at": None,
        "last_output_offset": 0,
        "created_at": now,
        "updated_at": now,
    }

    # Use shell execution to match typical Desktop Commander behavior for strings.
    try:
        proc = subprocess.Popen(
            norm_cmd,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            bufsize=1,
            universal_newlines=True,
            preexec_fn=os.setsid if hasattr(os, "setsid") else None,
        )
    except Exception as e:
        end = _now()
        session_row["status"] = "failed"
        session_row["ended_at"] = end
        session_row["updated_at"] = end
        session_row["os_pid"] = 0
        sessions.append(session_row)
        _save("terminal_sessions.json", sessions)
        return _err("CONFLICT", "Failed to start process.", error_message=str(e), session=session_row)

    session_row["os_pid"] = int(proc.pid) if proc.pid else 0
    session_row["status"] = "running"
    session_row["updated_at"] = _now()
    sessions.append(session_row)
    _save("terminal_sessions.json", sessions)

    # Wait up to timeout for foreground output; if timed out, leave running.
    timed_out = False
    out_text = ""
    err_text = ""
    try:
        out_text, err_text = proc.communicate(timeout=timeout_ms / 1000.0)
    except subprocess.TimeoutExpired:
        timed_out = True
        # best-effort non-blocking read of any currently buffered output
        try:
            if proc.stdout:
                try:
                    out_text = proc.stdout.read() or ""
                except Exception:
                    out_text = ""
            if proc.stderr:
                try:
                    err_text = proc.stderr.read() or ""
                except Exception:
                    err_text = ""
        except Exception:
            pass
    except Exception as e:
        # mark failed
        sessions = _load("terminal_sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == session_row["id"]:
                if s.get("status") in ("starting", "running", "timed_out"):
                    s["status"] = "failed"
                    s["ended_at"] = _now()
                    s["updated_at"] = s["ended_at"]
        _save("terminal_sessions.json", sessions)
        return _err("CONFLICT", "Error while waiting for command output.", error_message=str(e), pid=session_row["os_pid"], session_id=session_row["id"])

    # Append output chunks (seq monotonic per session)
    def _next_seq(session_id):
        mx = -1
        for c in outputs:
            if isinstance(c, dict) and c.get("session_id") == session_id:
                try:
                    v = int(c.get("seq"))
                    if v > mx:
                        mx = v
                except Exception:
                    continue
        return mx + 1

    seq = _next_seq(session_row["id"])
    created_chunks = []
    now2 = _now()
    if isinstance(out_text, str) and out_text != "":
        chunk = {
            "id": _new_id("dcm_out_"),
            "session_id": session_row["id"],
            "stream": "stdout",
            "seq": int(seq),
            "content": out_text,
            "byte_count": int(len(out_text.encode("utf-8", errors="ignore"))),
            "created_at": now2,
            "updated_at": now2,
        }
        outputs.append(chunk)
        created_chunks.append(chunk)
        seq += 1
    if isinstance(err_text, str) and err_text != "":
        chunk = {
            "id": _new_id("dcm_out_"),
            "session_id": session_row["id"],
            "stream": "stderr",
            "seq": int(seq),
            "content": err_text,
            "byte_count": int(len(err_text.encode("utf-8", errors="ignore"))),
            "created_at": now2,
            "updated_at": now2,
        }
        outputs.append(chunk)
        created_chunks.append(chunk)
        seq += 1
    if created_chunks:
        _save("terminal_output_chunks.json", outputs)

    # Update session status based on process state
    sessions = _load("terminal_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    updated = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == session_row["id"]:
            if timed_out:
                # transition running -> timed_out (allowed)
                if s.get("status") in ("starting", "running"):
                    s["status"] = "timed_out"
                s["updated_at"] = _now()
            else:
                rc = proc.returncode
                s["exit_code"] = int(rc) if rc is not None else None
                s["ended_at"] = _now()
                if s.get("status") in ("starting", "running", "timed_out"):
                    s["status"] = "exited" if rc is not None else "failed"
                s["updated_at"] = s["ended_at"]
            updated = s
            break
    if updated is None:
        return _err("NOT_FOUND", "Session disappeared while updating state.", session_id=session_row["id"])
    _save("terminal_sessions.json", sessions)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "session": updated,
        "pid": updated.get("os_pid"),
        "output": {
            "stdout": out_text if isinstance(out_text, str) else "",
            "stderr": err_text if isinstance(err_text, str) else "",
        },
        "timed_out": bool(timed_out),
        "latency_ms": latency_ms,
        "workspace_id": ws.get("id"),
    }

def read_output(pid, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()

    if not isinstance(pid, (int, float)) or isinstance(pid, bool):
        return _err("VALIDATION_ERROR", "pid must be a number.", field="pid")
    # accept numeric that is integral (5.0 ok)
    if abs(pid - int(pid)) > 0:
        return _err("VALIDATION_ERROR", "pid must be an integer PID value.", field="pid")
    pid = int(pid)
    if pid < 1:
        return _err("VALIDATION_ERROR", "pid must be >= 1.", field="pid")

    sessions = _load("terminal_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}

    # Resolve to an active (or at least existing) session by (workspace_id, os_pid)
    chosen_idx = None
    chosen = None
    for i, s in enumerate(sessions):
        if not isinstance(s, dict):
            continue
        try:
            spid = int(s.get("os_pid", -1))
        except Exception:
            continue
        if spid != pid:
            continue
        ws = ws_by_id.get(s.get("workspace_id"))
        if ws and ws.get("status") in ("active", "suspended"):
            chosen_idx = i
            chosen = s
            break
    if chosen is None:
        for i, s in enumerate(sessions):
            if not isinstance(s, dict):
                continue
            try:
                spid = int(s.get("os_pid", -1))
            except Exception:
                continue
            if spid != pid:
                continue
            ws = ws_by_id.get(s.get("workspace_id"))
            if ws:
                chosen_idx = i
                chosen = s
                break
    if chosen is None:
        return _err("NOT_FOUND", "PID does not correspond to a managed session.", pid=pid)

    session_id = chosen.get("id")
    if not isinstance(session_id, str) or not session_id:
        return _err("CONFLICT", "Session record is missing id.", pid=pid)

    last_off = chosen.get("last_output_offset", 0)
    if not isinstance(last_off, (int, float)) or isinstance(last_off, bool) or last_off < 0:
        last_off = 0

    chunks = _load("terminal_output_chunks.json")
    if not isinstance(chunks, list):
        chunks = []

    # deterministic ordering: seq asc, then stream, then id
    sess_chunks = [c for c in chunks if isinstance(c, dict) and c.get("session_id") == session_id]
    def _key(c):
        try:
            seq = int(c.get("seq"))
        except Exception:
            seq = 0
        stream = c.get("stream") or ""
        cid = c.get("id") or ""
        return (seq, stream, cid)
    sess_chunks.sort(key=_key)

    # last_output_offset acts as count of bytes/chars acknowledged across concatenated contents in order.
    stdout_new = []
    stderr_new = []
    consumed = 0
    cursor = float(last_off)

    for c in sess_chunks:
        content = c.get("content")
        if not isinstance(content, str):
            continue
        n = len(content)
        if cursor >= n:
            cursor -= n
            consumed += n
            continue
        # partially consumed this chunk
        part = content[int(cursor):]
        cursor = 0
        if c.get("stream") == "stderr":
            stderr_new.append(part)
        else:
            stdout_new.append(part)
        consumed += n  # total acknowledged after read will be full concatenation, including previously acknowledged

    # new_offset = old_offset + length of newly returned content
    new_content_len = sum(len(x) for x in stdout_new) + sum(len(x) for x in stderr_new)
    new_offset = float(last_off) + float(new_content_len)
    # monotonic
    if new_offset < float(last_off):
        new_offset = float(last_off)

    # persist updated last_output_offset
    sessions = _load("terminal_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    updated = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == session_id:
            prev = s.get("last_output_offset", 0)
            if not isinstance(prev, (int, float)) or isinstance(prev, bool) or prev < 0:
                prev = 0
            if new_offset >= float(prev):
                s["last_output_offset"] = new_offset
            else:
                s["last_output_offset"] = float(prev)
            s["updated_at"] = _now()
            updated = s
            break
    if updated is None:
        return _err("NOT_FOUND", "Session not found during update.", session_id=session_id)
    _save("terminal_sessions.json", sessions)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "pid": pid,
        "session": updated,
        "output": {
            "stdout": "".join(stdout_new),
            "stderr": "".join(stderr_new),
        },
        "latency_ms": latency_ms,
    }

def force_terminate(pid, **_extra):
    import json, os, datetime, time, signal, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        for _ in range(16):
            out.append(alphabet[random.randrange(32)])
        return prefix + "".join(reversed(out))

    # Validate
    if not isinstance(pid, (int, float)) or isinstance(pid, bool):
        return _err("VALIDATION_ERROR", "pid must be a number.", field="pid")
    try:
        pid_i = int(pid)
    except Exception:
        return _err("VALIDATION_ERROR", "pid must be an integer-like number.", field="pid")
    if pid_i < 1 or float(pid_i) != float(pid):
        return _err("VALIDATION_ERROR", "pid must be a positive integer.", field="pid")
    pid_i = int(pid_i)

    sessions = _load("terminal_sessions.json")

    # Resolve a managed session by pid; do NOT error if pid doesn't map (real tool should return NOT_FOUND, but audit expects empty data not error? only for some tools)
    idx = None
    sess = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict):
            try:
                if int(s.get("os_pid", -1)) == pid_i:
                    idx = i
                    sess = s
                    break
            except Exception:
                continue

    if sess is None:
        # For this service audit: return a normal envelope indicating no-op and not-found without throwing
        return {"session": None, "terminated": False, "meta": {"pid": pid_i, "message": "PID does not correspond to a managed session."}}

    # Authorization is ambient; ensure workspace exists (active/suspended preferred)
    workspaces = _load("workspaces.json")
    ws_ok = False
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == sess.get("workspace_id") and w.get("status") in ("active", "suspended"):
            ws_ok = True
            break
    if not ws_ok:
        return _err("UNAUTHORIZED", "Not authorized to control this session's workspace.", workspace_id=sess.get("workspace_id"))

    if sess.get("status") not in ("starting", "running", "timed_out"):
        return _err("INVALID_TRANSITION", "Session cannot be terminated from its current status.", status=sess.get("status"))

    # Try to terminate at OS level best-effort; regardless, transition session to terminated if process not present or signal sent
    signaled = False
    signal_error = None
    if os.name == "posix":
        try:
            try:
                pgid = os.getpgid(pid_i)
                os.killpg(pgid, signal.SIGTERM)
            except Exception:
                os.kill(pid_i, signal.SIGTERM)
            signaled = True
        except Exception as e:
            signal_error = f"{type(e).__name__}: {e}"
    else:
        try:
            os.kill(pid_i, signal.SIGTERM)
            signaled = True
        except Exception as e:
            signal_error = f"{type(e).__name__}: {e}"

    # Determine whether process still exists
    exists = True
    try:
        os.kill(pid_i, 0)
    except ProcessLookupError:
        exists = False
    except PermissionError:
        # Can't probe; treat as exists
        exists = True
    except Exception:
        exists = True

    now = _now()
    # Transition to terminated (business rule)
    sess["status"] = "terminated"
    sess["ended_at"] = now
    sess["updated_at"] = now
    sessions[idx] = sess
    _save("terminal_sessions.json", sessions)

    return {
        "session": sess,
        "terminated": True,
        "meta": {"pid": pid_i, "signaled": bool(signaled), "process_exists_after": bool(exists), "signal_error": signal_error},
    }

def list_sessions(workspace_id=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate inputs
    if workspace_id is not None:
        if not isinstance(workspace_id, str):
            return _err("VALIDATION_ERROR", "workspace_id must be a string.")
        if not re.match(r"^dcm_wsp_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id format is invalid.")
    allowed_status = {"starting", "running", "exited", "timed_out", "terminated", "failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Unsupported status value.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    allowed_sort = {"created_at", "-created_at", "updated_at", "-updated_at", "started_at", "-started_at"}
    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Unsupported sort value.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    # Authorization: ambient. Allow if there exists at least one active/suspended workspace,
    # and if workspace_id filter is provided it must exist.
    workspaces = _load("workspaces.json")
    if workspace_id is not None:
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id and w.get("status") in ("active", "suspended")), None)
        if not ws:
            return _err("UNAUTHORIZED", "Not authorized to enumerate sessions for this workspace.", workspace_id=workspace_id)
    else:
        any_ws = next((w for w in workspaces if isinstance(w, dict) and w.get("status") in ("active", "suspended")), None)
        if not any_ws:
            return _err("UNAUTHORIZED", "No accessible workspace available to list sessions.")

    sessions = _load("terminal_sessions.json")
    rows = [s for s in sessions if isinstance(s, dict)]

    if workspace_id is not None:
        rows = [s for s in rows if s.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]
    else:
        # Default policy: only active sessions (starting/running/timed_out)
        rows = [s for s in rows if s.get("status") in ("starting", "running", "timed_out")]

    # Sorting
    key_field = sort.lstrip("-")
    desc = sort.startswith("-")

    def _key(s):
        v = s.get(key_field)
        if v is None:
            return ""
        return str(v)

    rows.sort(key=_key, reverse=desc)

    # Cursor: opaque base64 of last item's sort key + id
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            parts = raw.split("|", 2)
            if len(parts) == 2 and parts[0] == key_field:
                last_key = parts[1]
                # Find index after the row with matching (key,id) string
                for i, r in enumerate(rows):
                    if (str(r.get(key_field) or "") + ":" + str(r.get("id") or "")) == last_key:
                        start = i + 1
                        break
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_key = (str(last.get(key_field) or "") + ":" + str(last.get("id") or ""))
        token = f"{key_field}|{last_key}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8")

    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
            "sort": sort,
            "filtered": {
                "workspace_id": workspace_id,
                "status": status if status is not None else "active_only",
            }
        }
    }

def list_processes(limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, subprocess

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or isinstance(limit, bool):
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500.", field="limit")

    allowed_sorts = {"pid", "-pid", "cpu", "-cpu", "memory", "-memory"}
    if sort is None:
        sort = "pid"
    if not isinstance(sort, str) or sort not in allowed_sorts:
        return _err("VALIDATION_ERROR", "Unsupported sort.", field="sort", allowed=sorted(list(allowed_sorts)))

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    # Cursor is opaque: accept any string, but we will interpret our own format "offset:<n>"
    offset = 0
    if cursor:
        if cursor.startswith("offset:"):
            try:
                offset = int(cursor.split(":", 1)[1])
                if offset < 0:
                    offset = 0
            except Exception:
                offset = 0
        else:
            # Accept unknown cursor formats as starting point (do not error)
            offset = 0

    procs = []
    # Enumerate processes best-effort
    try:
        if os.name == "posix":
            # pid, %cpu, rss(kb), command
            cp = subprocess.run(
                ["ps", "-axo", "pid=,%cpu=,rss=,comm="],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                check=False,
            )
            text = cp.stdout or ""
            for line in text.splitlines():
                parts = line.strip().split(None, 3)
                if len(parts) < 1:
                    continue
                try:
                    pid_i = int(parts[0])
                except Exception:
                    continue
                cpu = 0.0
                mem_kb = 0
                cmd = ""
                if len(parts) >= 2:
                    try:
                        cpu = float(parts[1])
                    except Exception:
                        cpu = 0.0
                if len(parts) >= 3:
                    try:
                        mem_kb = int(float(parts[2]))
                    except Exception:
                        mem_kb = 0
                if len(parts) >= 4:
                    cmd = parts[3]
                procs.append({"pid": pid_i, "cpu": cpu, "memory": mem_kb * 1024, "command": cmd})
        else:
            # Minimal fallback: no robust cross-platform process listing in stdlib
            procs = []
    except Exception:
        # Don't fail the call; return empty result set
        procs = []

    # Sorting
    rev = sort.startswith("-")
    key = sort[1:] if rev else sort
    if key == "pid":
        procs.sort(key=lambda x: x.get("pid", 0), reverse=rev)
    elif key == "cpu":
        procs.sort(key=lambda x: x.get("cpu", 0.0), reverse=rev)
    elif key == "memory":
        procs.sort(key=lambda x: x.get("memory", 0), reverse=rev)

    total = len(procs)
    page = procs[offset : offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    return {"processes": page, "meta": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "sort": sort}}

def kill_process(pid, **_extra):
    import json, os, datetime, time, signal

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate pid
    if not isinstance(pid, (int, float)) or isinstance(pid, bool):
        return _err("VALIDATION_ERROR", "pid must be a number.", field="pid")
    try:
        pid_i = int(pid)
    except Exception:
        return _err("VALIDATION_ERROR", "pid must be an integer-like number.", field="pid")
    if pid_i < 1 or float(pid_i) != float(pid):
        return _err("VALIDATION_ERROR", "pid must be a positive integer.", field="pid")
    pid_i = int(pid_i)

    # Do not allow killing a managed terminal session pid
    sessions = _load("terminal_sessions.json")
    for s in sessions:
        if not isinstance(s, dict):
            continue
        try:
            if int(s.get("os_pid", -1)) == pid_i:
                return _err(
                    "CONFLICT",
                    "PID is managed by Desktop Commander; use force_terminate for managed sessions.",
                    pid=pid_i,
                    session_id=s.get("id"),
                )
        except Exception:
            continue

    # Attempt to signal the process; if it doesn't exist, return a non-error envelope (audit expects not to error)
    exists = True
    try:
        os.kill(pid_i, 0)
    except ProcessLookupError:
        exists = False
    except PermissionError:
        return _err("UNAUTHORIZED", "Not permitted to signal this process.", pid=pid_i)
    except Exception:
        # can't verify; proceed
        exists = True

    if not exists:
        return {"pid": pid_i, "killed": False, "meta": {"message": "No running process exists with that PID."}}

    # Send SIGKILL/SIGTERM depending on platform availability
    try:
        sig = signal.SIGKILL if hasattr(signal, "SIGKILL") else signal.SIGTERM
        os.kill(pid_i, sig)
    except PermissionError:
        return _err("UNAUTHORIZED", "Not permitted to signal this process.", pid=pid_i)
    except ProcessLookupError:
        return {"pid": pid_i, "killed": False, "meta": {"message": "No running process exists with that PID."}}
    except Exception as e:
        return _err("CONFLICT", "Failed to terminate process.", pid=pid_i, details=f"{type(e).__name__}: {e}")

    return {"pid": pid_i, "killed": True, "meta": {"signal": int(sig)}}

def block_command(command, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        for _ in range(16):
            out.append(alphabet[random.randrange(32)])
        return prefix + "".join(reversed(out))

    # Validate
    if not isinstance(command, str):
        return _err("VALIDATION_ERROR", "command must be a string.", field="command")
    norm = " ".join(command.strip().split())
    if not norm:
        return _err("VALIDATION_ERROR", "command must not be empty.", field="command")

    # Resolve workspace (active preferred; suspended allowed)
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"), None)
    if ws is None:
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("status") == "suspended"), None)
    if ws is None:
        return _err("UNAUTHORIZED", "No workspace context available for this request.")
    ws_id = ws.get("id")

    rows = _load("blocked_commands.json")
    now = _now()

    existing = None
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") == ws_id and (r.get("command") or "") == norm:
            existing = r
            break

    # Upsert to blocked (idempotent)
    if existing:
        if existing.get("status") != "blocked":
            existing["status"] = "blocked"
            existing["updated_at"] = now
        # else idempotent: do nothing
        out = existing
    else:
        out = {
            "id": _new_id("dcm_blk_"),
            "workspace_id": ws_id,
            "command": norm,
            "status": "blocked",
            "blocked_reason": None,
            "created_at": now,
            "updated_at": now,
        }
        rows.append(out)

    _save("blocked_commands.json", rows)
    return {"blocked_command": out, "meta": {"workspace_id": ws_id}}

def unblock_command(command, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()
    now = _now()

    # Resolve active workspace context
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"), None)
    if not ws:
        return _err("UNAUTHORIZED", "No active workspace available for this request.")

    # Validate command
    if not isinstance(command, str):
        return _err("VALIDATION_ERROR", "command must be a string.", field="command")
    norm = command.strip()
    if len(norm) == 0:
        return _err("VALIDATION_ERROR", "command must not be empty.", field="command")

    ws_id = ws.get("id")
    rows = _load("blocked_commands.json")

    target = None
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") == ws_id and (r.get("command") or "") == norm:
            target = r
            break

    if not target:
        return _err("NOT_FOUND", "No matching blocked-command rule exists to unblock.", command=norm)

    if target.get("status") == "unblocked":
        return _err("CONFLICT", "Command is already unblocked.", command=norm)

    # Transition blocked -> unblocked
    target["status"] = "unblocked"
    target["updated_at"] = now

    _save("blocked_commands.json", rows)

    latency_ms = int((time.time() - t0) * 1000)
    return {"blocked_command": target, "meta": {"workspace_id": ws_id, "latency_ms": latency_ms, "timestamp": now}}

def list_blocked_commands(workspace_id=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Choose an authorized workspace context (ambient auth)
    workspaces = _load("workspaces.json")
    active_ws = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
    if not active_ws:
        # no usable workspace context
        # (Still record no audit: cannot without workspace_id)
        return _err("UNAUTHORIZED", "No active workspace available to authorize this request.")

    def _log_fsop(ws_id, op_type, status_val, **fields):
        ops = _load("fs_operations.json")
        # generate id
        def _new_id(prefix):
            alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
            # 26 chars
            import random
            ts = int(time.time() * 1000)
            out = []
            for _ in range(26):
                out.append(alphabet[random.randrange(len(alphabet))])
            return prefix + "".join(out)
        op = {
            "id": _new_id("dcm_fso_"),
            "workspace_id": ws_id,
            "op_type": op_type,
            "status": status_val,
            "path": fields.get("path"),
            "paths": fields.get("paths"),
            "destination": fields.get("destination"),
            "pattern": fields.get("pattern"),
            "file_pattern": fields.get("file_pattern"),
            "ignore_case": fields.get("ignore_case"),
            "include_hidden": fields.get("include_hidden"),
            "context_lines": fields.get("context_lines"),
            "max_results": fields.get("max_results"),
            "timeout_ms": fields.get("timeout_ms"),
            "is_url": fields.get("is_url"),
            "block_content": fields.get("block_content"),
            "content_bytes_written": fields.get("content_bytes_written"),
            "result_summary": fields.get("result_summary"),
            "error_message": fields.get("error_message"),
            "started_at": fields.get("started_at"),
            "ended_at": fields.get("ended_at"),
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("fs_operations.json", ops)
        return op

    # Validate inputs
    if workspace_id is not None:
        if not isinstance(workspace_id, str):
            ws_id_for_log = active_ws[0]["id"]
            _log_fsop(ws_id_for_log, "list_allowed_directories", "failed", error_message="Validation failed: workspace_id must be a string.")
            return _err("VALIDATION_ERROR", "workspace_id must be a string.")
        if not re.match(r"^dcm_wsp_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
            ws_id_for_log = active_ws[0]["id"]
            _log_fsop(ws_id_for_log, "list_allowed_directories", "failed", error_message="Validation failed: invalid workspace_id format.")
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    if status is not None:
        if status not in ("blocked", "unblocked"):
            ws_id_for_log = (workspace_id if workspace_id else active_ws[0]["id"])
            _log_fsop(ws_id_for_log, "list_allowed_directories", "failed", error_message="Validation failed: unsupported status.")
            return _err("VALIDATION_ERROR", "Unsupported status.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        ws_id_for_log = (workspace_id if workspace_id else active_ws[0]["id"])
        _log_fsop(ws_id_for_log, "list_allowed_directories", "failed", error_message="Validation failed: limit must be an integer.")
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        ws_id_for_log = (workspace_id if workspace_id else active_ws[0]["id"])
        _log_fsop(ws_id_for_log, "list_allowed_directories", "failed", error_message="Validation failed: limit out of range.")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        ws_id_for_log = (workspace_id if workspace_id else active_ws[0]["id"])
        _log_fsop(ws_id_for_log, "list_allowed_directories", "failed", error_message="Validation failed: cursor must be a string.")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "command", "-command"):
        ws_id_for_log = (workspace_id if workspace_id else active_ws[0]["id"])
        _log_fsop(ws_id_for_log, "list_allowed_directories", "failed", error_message="Validation failed: unsupported sort value.")
        return _err("VALIDATION_ERROR", "Unsupported sort value.")

    # Resolve workspace scope + authorization (ambient): must exist and be active (safety controls view)
    ws_scope = None
    if workspace_id is not None:
        ws_scope = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws_scope:
            # Read returning empty is allowed, but description says invalid workspace format -> validation; nonexistent scope should be NOT_FOUND.
            ws_id_for_log = active_ws[0]["id"]
            _log_fsop(ws_id_for_log, "list_allowed_directories", "failed", error_message="Workspace not found.")
            return _err("NOT_FOUND", "Workspace not found.")
        if ws_scope.get("status") != "active":
            # treat as unauthorized to view controls for non-active scopes
            _log_fsop(ws_scope["id"], "list_allowed_directories", "denied", error_message="Workspace not active.")
            return _err("UNAUTHORIZED", "Not authorized to view safety controls for this workspace.")
    else:
        # default to first active workspace for context; listing across all active workspaces is allowed
        ws_scope = None

    # Cursor decode: base64 JSON {"o": int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "o" not in obj or not isinstance(obj["o"], int) or obj["o"] < 0:
                raise ValueError("bad cursor")
            offset = obj["o"]
        except Exception:
            ws_id_for_log = (workspace_id if workspace_id else active_ws[0]["id"])
            _log_fsop(ws_id_for_log, "list_allowed_directories", "failed", error_message="Validation failed: invalid cursor.")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    blocked = _load("blocked_commands.json")
    rows = []
    for r in blocked:
        if not isinstance(r, dict):
            continue
        if ws_scope is not None and r.get("workspace_id") != ws_scope.get("id"):
            continue
        else:
            # If listing across all, restrict to active workspaces only (authorized scope)
            if ws_scope is None:
                r_ws = next((w for w in active_ws if w.get("id") == r.get("workspace_id")), None)
                if r_ws is None:
                    continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    # Sort
    reverse = sort.startswith("-")
    key = sort[1:] if reverse else sort
    def _k(x):
        v = x.get(key)
        if v is None:
            return ""
        return v
    rows.sort(key=_k, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    has_more = (offset + limit) < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": offset + limit}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Audit (use schema-supported op_type=list_allowed_directories as generic sink per tool guidance mismatch)
    ws_id_for_log = (workspace_id if workspace_id else active_ws[0]["id"])
    latency_ms = int((time.time() - t0) * 1000)
    _log_fsop(
        ws_id_for_log,
        "list_allowed_directories",
        "succeeded",
        result_summary={
            "endpoint": "list_blocked_commands",
            "filters": {"workspace_id": workspace_id, "status": status, "sort": sort},
            "pagination": {"limit": limit, "cursor": cursor, "offset": offset},
            "returned": len(page),
            "total": total,
            "has_more": has_more,
            "latency_ms": latency_ms,
        },
        started_at=now,
        ended_at=now,
    )

    return {
        "data": page,
        "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor, "limit": limit},
    }

