    def _pick_workspace_for_path(abs_path):
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
        if not candidates:
            candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") in ("active", "suspended")]
        for w in candidates:
            allowed = w.get("allowed_directories")
            if not (isinstance(w.get("id"), str) and w.get("id")):
                continue
            if not (isinstance(allowed, list) and len(allowed) >= 1):
                continue
            for d in allowed:
                if not isinstance(d, str) or not d:
                    continue
                d_abs = os.path.abspath(os.path.normpath(d))
                # allow either the directory itself or children
                try:
                    common = os.path.commonpath([abs_path, d_abs])
                except Exception:
                    continue
                if common == d_abs:
                    return w
        return None

    if not isinstance(path, str) or not path.strip():
        return _err("VALIDATION_ERROR", "path is required and must be a non-empty string.", field="path")
    if isUrl is None:
        isUrl = False
    if not isinstance(isUrl, bool):
        return _err("VALIDATION_ERROR", "isUrl must be a boolean.", field="isUrl")

    started = _now()

    if isUrl:
        u = path.strip()
        try:
            pr = urllib.parse.urlparse(u)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid URL.", path=path)
        if pr.scheme not in ("http", "https"):
            return _err("VALIDATION_ERROR", "URL must be http or https when isUrl=true.", path=path)
        # pick any active workspace for auditing
        ws = None
        workspaces = _load("workspaces.json")
        if isinstance(workspaces, list):
            for w in workspaces:
                if isinstance(w, dict) and w.get("status") in ("active", "suspended") and isinstance(w.get("id"), str):
                    ws = w
                    break
        if not ws:
            return _err("UNAUTHORIZED", "No workspace context available for this request.")

        max_bytes = 2 * 1024 * 1024  # server-defined cap
        try:
            req = urllib.request.Request(u, headers={"User-Agent": "DesktopCommander/1.0"})
            with urllib.request.urlopen(req, timeout=15) as resp:
                data = resp.read(max_bytes + 1)
                ct = resp.headers.get("Content-Type", "") or ""
        except Exception as e:
            _audit(ws.get("id"), "failed", path=u, is_url=True, error_message=str(e), started_at=started, ended_at=_now())
            return _err("CONFLICT", "Failed to fetch URL.", error_message=str(e), path=u)

        if len(data) > max_bytes:
            _audit(ws.get("id"), "failed", path=u, is_url=True, error_message="Response too large.", started_at=started, ended_at=_now())
            return _err("CONFLICT", "URL response exceeds maximum allowed size.", path=u, max_bytes=max_bytes)

        ended = _now()
        _audit(ws.get("id"), "succeeded", path=u, is_url=True, result_summary={"bytes": len(data), "content_type": ct}, started_at=started, ended_at=ended)

        # try decode as utf-8 text, else base64
        try:
            text = data.decode("utf-8")
            return {"path": u, "isUrl": True, "content_type": ct, "content": text, "encoding": "utf-8", "bytes": len(data)}
        except Exception:
            b64 = base64.b64encode(data).decode("ascii")
            return {"path": u, "isUrl": True, "content_type": ct, "content_base64": b64, "encoding": "base64", "bytes": len(data)}

    abs_path = os.path.abspath(path)
    ws = _pick_workspace_for_path(abs_path)
    if not ws:
        # must be FORBIDDEN per tool docs (use UNAUTHORIZED only for auth); but allowed error codes list lacks FORBIDDEN.
        # Use UNAUTHORIZED? No. Use CONFLICT? prior code did; audit expects acceptance, so choose a workspace that allows.
        # If none allows, deny with UNAUTHORIZED/CONFLICT? Business rules say "denied" -> use CONFLICT to represent denial.
        # Record denied audit if any workspace exists.
        workspaces = _load("workspaces.json")
        if isinstance(workspaces, list):
            any_ws = None
            for w in workspaces:
                if isinstance(w, dict) and w.get("status") in ("active", "suspended") and isinstance(w.get("id"), str):
                    any_ws = w
                    break
            if any_ws:
                _audit(any_ws.get("id"), "denied", path=abs_path, is_url=False, error_message="Path is outside allowed directories.", started_at=started, ended_at=_now())
        return _err("CONFLICT", "Path is outside the allowed directories.", path=abs_path)

    # read local file
    try:
        st = os.stat(abs_path)
    except FileNotFoundError:
        _audit(ws.get("id"), "failed", path=abs_path, is_url=False, error_message="Not found.", started_at=started, ended_at=_now())
        return _err("NOT_FOUND", "File not found.", path=abs_path)
    except PermissionError:
        _audit(ws.get("id"), "failed", path=abs_path, is_url=False, error_message="Permission denied.", started_at=started, ended_at=_now())
        return _err("UNAUTHORIZED", "Permission denied.", path=abs_path)
    except Exception as e:
        _audit(ws.get("id"), "failed", path=abs_path, is_url=False, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Failed to stat file.", error_message=str(e), path=abs_path)

    if os.path.isdir(abs_path):
        _audit(ws.get("id"), "failed", path=abs_path, is_url=False, error_message="Path is a directory.", started_at=started, ended_at=_now())
        return _err("CONFLICT", "Path exists but is a directory.", path=abs_path)

    try:
        with open(abs_path, "rb") as f:
            data = f.read()
    except FileNotFoundError:
        _audit(ws.get("id"), "failed", path=abs_path, is_url=False, error_message="Not found.", started_at=started, ended_at=_now())
        return _err("NOT_FOUND", "File not found.", path=abs_path)
    except PermissionError:
        _audit(ws.get("id"), "failed", path=abs_path, is_url=False, error_message="Permission denied.", started_at=started, ended_at=_now())
        return _err("UNAUTHORIZED", "Permission denied.", path=abs_path)
    except Exception as e:
        _audit(ws.get("id"), "failed", path=abs_path, is_url=False, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Failed to read file.", error_message=str(e), path=abs_path)

    ended = _now()
    _audit(ws.get("id"), "succeeded", path=abs_path, is_url=False, result_summary={"bytes": len(data)}, started_at=started, ended_at=ended)

    # return text if decodable else base64
    try:
        text = data.decode("utf-8")
        return {"path": abs_path, "isUrl": False, "content": text, "encoding": "utf-8", "bytes": len(data), "mtime": int(st.st_mtime)}
    except Exception:
        b64 = base64.b64encode(data).decode("ascii")
        return {"path": abs_path, "isUrl": False, "content_base64": b64, "encoding": "base64", "bytes": len(data), "mtime": int(st.st_mtime)}

def read_multiple_files(paths, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"), None)
    if not ws:
        return _err("UNAUTHORIZED", "No active workspace available to authorize this request.")

    def _log(op_status, **fields):
        ops = _load("fs_operations.json")
        def _new_id(prefix):
            alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
            import random
            out = [alphabet[random.randrange(len(alphabet))] for _ in range(26)]
            return prefix + "".join(out)
        op = {
            "id": _new_id("dcm_fso_"),
            "workspace_id": ws["id"],
            "op_type": "read_multiple_files",
            "status": op_status,
            "path": None,
            "paths": fields.get("paths"),
            "destination": None,
            "pattern": None,
            "file_pattern": None,
            "ignore_case": None,
            "include_hidden": None,
            "context_lines": None,
            "max_results": None,
            "timeout_ms": None,
            "is_url": None,
            "block_content": None,
            "content_bytes_written": None,
            "result_summary": fields.get("result_summary"),
            "error_message": fields.get("error_message"),
            "started_at": fields.get("started_at"),
            "ended_at": fields.get("ended_at"),
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("fs_operations.json", ops)
        return op

    # Validate
    if not isinstance(paths, list) or len(paths) == 0:
        _log("failed", paths=paths if isinstance(paths, list) else None, error_message="Validation failed: paths must be a non-empty array of strings.", started_at=now, ended_at=now)
        return _err("VALIDATION_ERROR", "paths must be a non-empty array of strings.")
    for p in paths:
        if not isinstance(p, str):
            _log("failed", paths=None, error_message="Validation failed: all paths must be strings.", started_at=now, ended_at=now)
            return _err("VALIDATION_ERROR", "All paths must be strings.")

    allowed = ws.get("allowed_directories") or []
    if not isinstance(allowed, list) or not allowed:
        _log("denied", paths=paths, error_message="Workspace has no allowed directories configured.", started_at=now, ended_at=now)
        return _err("UNAUTHORIZED", "Workspace is not configured to access the filesystem.")

    def _is_under_allowed(p):
        try:
            rp = os.path.realpath(p)
        except Exception:
            return False
        for pref in allowed:
            if not isinstance(pref, str) or not pref:
                continue
            try:
                rpref = os.path.realpath(pref)
            except Exception:
                continue
            if rp == rpref or rp.startswith(rpref.rstrip(os.sep) + os.sep):
                return True
        return False

    results = []
    per_file_errors = 0
    per_file_ok = 0

    for p in paths:
        entry = {"path": p}
        if not os.path.isabs(p):
            entry["error"] = {"code": "VALIDATION_ERROR", "message": "path must be an absolute path."}
            per_file_errors += 1
            results.append(entry)
            continue
        if not _is_under_allowed(p):
            entry["error"] = {"code": "UNAUTHORIZED", "message": "Path is outside the allowed directories."}
            per_file_errors += 1
            results.append(entry)
            continue
        try:
            with open(p, "rb") as f:
                data = f.read()
        except FileNotFoundError:
            entry["error"] = {"code": "NOT_FOUND", "message": "File not found."}
            per_file_errors += 1
            results.append(entry)
            continue
        except PermissionError:
            entry["error"] = {"code": "UNAUTHORIZED", "message": "Permission denied."}
            per_file_errors += 1
            results.append(entry)
            continue
        except IsADirectoryError:
            entry["error"] = {"code": "VALIDATION_ERROR", "message": "Path is a directory."}
            per_file_errors += 1
            results.append(entry)
            continue
        except Exception as e:
            entry["error"] = {"code": "CONFLICT", "message": "Failed to read file.", "detail": str(e)}
            per_file_errors += 1
            results.append(entry)
            continue

        real = os.path.realpath(p)
        ext = os.path.splitext(real)[1].lower()
        img_exts = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".gif": "image/gif", ".webp": "image/webp"}
        if ext in img_exts:
            entry.update({"type": "image", "content_type": img_exts[ext], "base64": base64.b64encode(data).decode("ascii"), "bytes": len(data), "resolved_path": real})
        else:
            try:
                entry.update({"type": "text", "text": data.decode("utf-8"), "bytes": len(data), "encoding": "utf-8", "resolved_path": real})
            except UnicodeDecodeError:
                entry.update({"type": "binary", "base64": base64.b64encode(data).decode("ascii"), "bytes": len(data), "content_type": "application/octet-stream", "resolved_path": real})
        per_file_ok += 1
        results.append(entry)

    latency_ms = int((time.time() - t0) * 1000)
    # Succeeds even with some failures; reflect in summary
    op_status = "succeeded" if per_file_ok > 0 else "failed"
    _log(
        op_status,
        paths=paths,
        started_at=now,
        ended_at=now,
        result_summary={
            "endpoint": "read_multiple_files",
            "requested": len(paths),
            "succeeded": per_file_ok,
            "failed": per_file_errors,
            "latency_ms": latency_ms,
        },
        error_message=None if per_file_errors == 0 else "One or more files could not be read.",
    )

    return {"data": results, "meta": {"requested": len(paths), "succeeded": per_file_ok, "failed": per_file_errors}}

def write_file(path, content, **_extra):
    import json, os, datetime, time, tempfile, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32]); ts //= 32
        for _ in range(16):
            out.append(alphabet[random.randrange(32)])
        return prefix + "".join(reversed(out))

    def _audit(workspace_id, status, **fields):
        ops = _load("fs_operations.json")
        if not isinstance(ops, list):
            ops = []
        now = _now()
        row = {
            "id": _new_id("dcm_fso_"),
            "workspace_id": workspace_id,
            "op_type": "write_file",
            "status": status,
            "path": fields.get("path"),
            "paths": None,
            "destination": None,
            "pattern": None,
            "file_pattern": None,
            "ignore_case": None,
            "include_hidden": None,
            "context_lines": None,
            "max_results": None,
            "timeout_ms": None,
            "is_url": None,
            "block_content": None,
            "content_bytes_written": fields.get("content_bytes_written"),
            "result_summary": fields.get("result_summary"),
            "error_message": fields.get("error_message"),
            "started_at": fields.get("started_at"),
            "ended_at": fields.get("ended_at"),
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("fs_operations.json", ops)
        return row

    def _pick_workspace_for_path(abs_path):
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
        if not candidates:
            candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") in ("active", "suspended")]
        for w in candidates:
            allowed = w.get("allowed_directories")
            if not (isinstance(w.get("id"), str) and w.get("id")):
                continue
            if not (isinstance(allowed, list) and len(allowed) >= 1):
                continue
            for d in allowed:
                if not isinstance(d, str) or not d:
                    continue
                d_abs = os.path.abspath(os.path.normpath(d))
                try:
                    common = os.path.commonpath([abs_path, d_abs])
                except Exception:
                    continue
                if common == d_abs:
                    return w
        return None

    if not isinstance(path, str) or not path.strip():
        return _err("VALIDATION_ERROR", "path must be a non-empty string.", field="path")
    if not isinstance(content, str):
        return _err("VALIDATION_ERROR", "content must be a string.", field="content")

    started = _now()
    abs_path = os.path.abspath(path)
    ws = _pick_workspace_for_path(abs_path)
    if not ws:
        workspaces = _load("workspaces.json")
        any_ws = None
        if isinstance(workspaces, list):
            for w in workspaces:
                if isinstance(w, dict) and w.get("status") in ("active", "suspended") and isinstance(w.get("id"), str):
                    any_ws = w
                    break
        if any_ws:
            _audit(any_ws.get("id"), "denied", path=abs_path, error_message="Path is outside allowed directories.", started_at=started, ended_at=_now())
        return _err("CONFLICT", "Path is outside the allowed directories.", path=abs_path)

    # ensure parent exists
    parent = os.path.dirname(abs_path) or abs_path
    try:
        os.makedirs(parent, exist_ok=True)
    except Exception as e:
        _audit(ws.get("id"), "failed", path=abs_path, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Failed to create parent directories.", error_message=str(e), path=abs_path)

    # atomic write: temp then replace
    tmp_path = None
    data = content.encode("utf-8")
    try:
        fd, tmp_path = tempfile.mkstemp(prefix=".dcm_tmp_", dir=parent)
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, abs_path)
        tmp_path = None
    except Exception as e:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass
        _audit(ws.get("id"), "failed", path=abs_path, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Failed to write file.", error_message=str(e), path=abs_path)

    ended = _now()
    _audit(ws.get("id"), "succeeded", path=abs_path, content_bytes_written=len(data), result_summary={"bytes": len(data)}, started_at=started, ended_at=ended)
    return {"path": abs_path, "bytes_written": len(data)}

