        }
        ops.append(row)
        _save("fs_operations.json", ops)
        return row

    def _pick_workspace_for_both(src_abs, dst_abs):
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
        if not candidates:
            candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") in ("active", "suspended")]
        for w in candidates:
            allowed = w.get("allowed_directories")
            if not (isinstance(w.get("id"), str) and w.get("id")):
                continue
            if not (isinstance(allowed, list) and len(allowed) >= 1):
                continue

            def ok(p):
                for d in allowed:
                    if not isinstance(d, str) or not d:
                        continue
                    d_abs = os.path.abspath(os.path.normpath(d))
                    try:
                        if os.path.commonpath([p, d_abs]) == d_abs:
                            return True
                    except Exception:
                        continue
                return False

            if ok(src_abs) and ok(dst_abs):
                return w
        return None

    if not isinstance(source, str) or not source.strip():
        return _err("VALIDATION_ERROR", "source must be a non-empty string.", field="source")
    if not isinstance(destination, str) or not destination.strip():
        return _err("VALIDATION_ERROR", "destination must be a non-empty string.", field="destination")

    started = _now()
    src = os.path.abspath(source)
    dst = os.path.abspath(destination)

    ws = _pick_workspace_for_both(src, dst)
    if not ws:
        workspaces = _load("workspaces.json")
        any_ws = None
        if isinstance(workspaces, list):
            for w in workspaces:
                if isinstance(w, dict) and w.get("status") in ("active", "suspended") and isinstance(w.get("id"), str):
                    any_ws = w
                    break
        if any_ws:
            _audit(any_ws.get("id"), "denied", path=src, destination=dst, error_message="Source or destination is outside allowed directories.", started_at=started, ended_at=_now())
