    if not os.path.exists(src):
        _audit(ws.get("id"), "failed", path=src, destination=dst, error_message="Source not found.", started_at=started, ended_at=_now())
        return _err("NOT_FOUND", "Source does not exist.", source=src)
    if os.path.exists(dst):
        _audit(ws.get("id"), "failed", path=src, destination=dst, error_message="Destination already exists.", started_at=started, ended_at=_now())
        return _err("CONFLICT", "Destination already exists.", destination=dst)

    # atomic from API perspective: use os.replace for same filesystem; else fall back to shutil.move but only return success if it finishes.
    try:
        os.makedirs(os.path.dirname(dst) or dst, exist_ok=True)
    except Exception as e:
        _audit(ws.get("id"), "failed", path=src, destination=dst, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Failed to create destination parent directories.", error_message=str(e), destination=dst)

    try:
        try:
            os.replace(src, dst)
        except OSError:
            shutil.move(src, dst)
    except Exception as e:
        _audit(ws.get("id"), "failed", path=src, destination=dst, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Move failed.", error_message=str(e), source=src, destination=dst)

    ended = _now()
    _audit(ws.get("id"), "succeeded", path=src, destination=dst, result_summary={"moved": True}, started_at=started, ended_at=ended)
    return {"destination": dst}

