    # timeout policy
    if timeoutMs is None:
        timeoutMs = ws.get("default_search_timeout_ms")
    try:
        timeoutMs = float(timeoutMs)
    except Exception:
        return _err("VALIDATION_ERROR", "timeoutMs must be a number.", field="timeoutMs")
    if timeoutMs < 1:
        return _err("VALIDATION_ERROR", "timeoutMs must be >= 1.", field="timeoutMs")
    mx = ws.get("max_search_timeout_ms")
    if not isinstance(mx, (int, float)) or isinstance(mx, bool) or float(mx) < 1:
