        return _err("CONFLICT", "timeoutMs exceeds workspace.max_search_timeout_ms; request denied by workspace policy.", timeoutMs=timeoutMs, max_search_timeout_ms=float(mx))

    if not os.path.exists(root):
        _audit(ws.get("id"), "failed", path=root, pattern=pattern.strip(), timeout_ms=timeoutMs, error_message="Not found.", started_at=started, ended_at=_now())
        return _err("NOT_FOUND", "Path does not exist.", path=root)

    needle = pattern.strip().lower()
    deadline = time.time() + (timeoutMs / 1000.0)

    matches = []
    walked = 0
    try:
        for dirpath, dirnames, filenames in os.walk(root):
            walked += 1
            if time.time() > deadline:
                break
            # include directories too (names containing pattern)
            for d in list(dirnames):
                if time.time() > deadline:
                    break
                if needle in d.lower():
                    matches.append(os.path.join(dirpath, d))
            for fn in filenames:
                if time.time() > deadline:
                    break
                if needle in fn.lower():
                    matches.append(os.path.join(dirpath, fn))
