        _audit(ws.get("id"), "failed", path=root, pattern=pattern.strip(), timeout_ms=timeoutMs, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Search failed.", error_message=str(e), path=root)

    ended = _now()
    timed_out = time.time() > deadline
    _audit(ws.get("id"), "succeeded", path=root, pattern=pattern.strip(), timeout_ms=timeoutMs, result_summary={"count": len(matches), "timed_out": bool(timed_out), "walked": walked}, started_at=started, ended_at=ended)
    return {"path": root, "pattern": pattern.strip(), "matches": matches, "count": len(matches), "timed_out": bool(timed_out)}

