        if maxResults > int(ws_cap):
            maxResults = int(ws_cap)

    if not os.path.exists(root):
        _audit(ws.get("id"), "failed", path=root, pattern=pattern.strip(), file_pattern=filePattern, ignore_case=ignoreCase, include_hidden=includeHidden, context_lines=contextLines, max_results=maxResults, timeout_ms=timeoutMs, error_message="Not found.", started_at=started, ended_at=_now())
        return _err("NOT_FOUND", "Path does not exist.", path=root)

    flags = re.MULTILINE
    if ignoreCase:
        flags |= re.IGNORECASE
    try:
        rx = re.compile(re.escape(pattern.strip()), flags)
    except Exception as e:
        return _err("VALIDATION_ERROR", "Invalid search pattern.", error_message=str(e), field="pattern")

    deadline = time.time() + (timeoutMs / 1000.0)
    ctx = int(contextLines) if contextLines is not None else 0
    fp = filePattern.strip() if isinstance(filePattern, str) and filePattern.strip() else None

    results = []
    files_scanned = 0
    files_matched = 0
    stopped_for_timeout = False

    def _match_file(name, relpath):
        if not fp:
            return True
        # support basic glob patterns; allow "**/" patterns loosely by matching against relpath with slashes
        rel = relpath.replace(os.sep, "/")
        if fnmatch.fnmatch(name, fp) or fnmatch.fnmatch(rel, fp) or fnmatch.fnmatch(rel, fp.lstrip("./")):
            return True
        return False

    try:
        for dirpath, dirnames, filenames in os.walk(root):
            if not includeHidden:
                dirnames[:] = [d for d in dirnames if not d.startswith(".")]
                filenames = [f for f in filenames if not f.startswith(".")]
            if time.time() > deadline:
                stopped_for_timeout = True
                break

            for fn in filenames:
                if time.time() > deadline:
                    stopped_for_timeout = True
                    break
                full = os.path.join(dirpath, fn)
                rel = os.path.relpath(full, root)
                if not _match_file(fn, rel):
                    continue
                files_scanned += 1
                try:
                    with open(full, "r", encoding="utf-8", errors="ignore") as f:
                        lines = f.read().splitlines()
                except Exception:
                    continue

                matched_in_file = False
                for i, line in enumerate(lines):
                    if rx.search(line):
                        matched_in_file = True
                        start = max(0, i - ctx)
                        end = min(len(lines), i + ctx + 1)
                        results.append({
                            "path": full,
                            "line": i + 1,
                            "match": line,
                            "context_before": lines[start:i],
                            "context_after": lines[i + 1:end],
                        })
                        if len(results) >= maxResults:
                            break
                if matched_in_file:
                    files_matched += 1
                if len(results) >= maxResults:
                    break
            if len(results) >= maxResults:
                break
    except Exception as e:
        _audit(ws.get("id"), "failed", path=root, pattern=pattern.strip(), file_pattern=filePattern, ignore_case=ignoreCase, include_hidden=includeHidden, context_lines=contextLines, max_results=maxResults, timeout_ms=timeoutMs, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Search failed.", error_message=str(e), path=root)

    ended = _now()
    _audit(
        ws.get("id"),
        "succeeded",
        path=root,
        pattern=pattern.strip(),
        file_pattern=filePattern,
        ignore_case=ignoreCase,
        include_hidden=includeHidden,
        context_lines=contextLines,
        max_results=maxResults,
        timeout_ms=timeoutMs,
        result_summary={"count": len(results), "files_scanned": files_scanned, "files_matched": files_matched, "timed_out": bool(stopped_for_timeout), "capped_max_results": maxResults},
        started_at=started,
        ended_at=ended,
    )
    return {
        "path": root,
        "pattern": pattern.strip(),
        "filePattern": filePattern,
        "ignoreCase": ignoreCase,
        "includeHidden": includeHidden,
        "contextLines": ctx,
        "maxResults": maxResults,
        "timeoutMs": timeoutMs,
        "matches": results,
        "count": len(results),
        "timed_out": bool(stopped_for_timeout),
    }

def get_file_info(path, **_extra):
    import json, os, datetime, time, stat, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32]); ts //= 32
        for _ in range(16):
            out.append(alphabet[random.randrange(32)])
        return prefix + "".join(reversed(out))

    def _audit(workspace_id, status, **fields):
        ops = _load("fs_operations.json")
        if not isinstance(ops, list):
            ops = []
        now = _now()
        row = {
            "id": _new_id("dcm_fso_"),
            "workspace_id": workspace_id,
            "op_type": "get_file_info",
            "status": status,
            "path": fields.get("path"),
            "paths": None,
            "destination": None,
            "pattern": None,
            "file_pattern": None,
            "ignore_case": None,
            "include_hidden": None,
            "context_lines": None,
            "max_results": None,
            "timeout_ms": None,
            "is_url": None,
            "block_content": None,
            "content_bytes_written": None,
            "result_summary": fields.get("result_summary"),
            "error_message": fields.get("error_message"),
            "started_at": fields.get("started_at"),
            "ended_at": fields.get("ended_at"),
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("fs_operations.json", ops)
        return row

    def _pick_workspace_for_path(abs_path):
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
        if not candidates:
            candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") in ("active", "suspended")]
        for w in candidates:
            allowed = w.get("allowed_directories")
            if not (isinstance(w.get("id"), str) and w.get("id")):
                continue
            if not (isinstance(allowed, list) and len(allowed) >= 1):
                continue
            for d in allowed:
                if not isinstance(d, str) or not d:
                    continue
                d_abs = os.path.abspath(os.path.normpath(d))
                try:
                    if os.path.commonpath([abs_path, d_abs]) == d_abs:
                        return w
                except Exception:
                    continue
        return None

    if not isinstance(path, str) or not path.strip():
        return _err("VALIDATION_ERROR", "path is required and must be a non-empty string.", field="path")

    started = _now()
    abs_path = os.path.abspath(path)
    ws = _pick_workspace_for_path(abs_path)
    if not ws:
        workspaces = _load("workspaces.json")
        any_ws = None
        if isinstance(workspaces, list):
            for w in workspaces:
                if isinstance(w, dict) and w.get("status") in ("active", "suspended") and isinstance(w.get("id"), str):
                    any_ws = w
                    break
        if any_ws:
            _audit(any_ws.get("id"), "denied", path=abs_path, error_message="Path is outside allowed directories.", started_at=started, ended_at=_now())
        return _err("CONFLICT", "Path is outside the allowlist.", path=abs_path)

    try:
        st = os.stat(abs_path)
    except FileNotFoundError:
        _audit(ws.get("id"), "failed", path=abs_path, error_message="Not found.", started_at=started, ended_at=_now())
        return _err("NOT_FOUND", "Entry does not exist.", path=abs_path)
    except PermissionError:
        _audit(ws.get("id"), "failed", path=abs_path, error_message="Permission denied.", started_at=started, ended_at=_now())
        return _err("UNAUTHORIZED", "Permission denied.", path=abs_path)
    except Exception as e:
        _audit(ws.get("id"), "failed", path=abs_path, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Failed to stat path.", error_message=str(e), path=abs_path)

    mode = st.st_mode
    typ = "directory" if stat.S_ISDIR(mode) else ("file" if stat.S_ISREG(mode) else "other")
    info = {
        "path": abs_path,
        "type": typ,
        "size": int(st.st_size),
        "mtime": int(st.st_mtime),
        "ctime": int(st.st_ctime),
        "mode": int(mode),
        "readable": os.access(abs_path, os.R_OK),
        "writable": os.access(abs_path, os.W_OK),
        "executable": os.access(abs_path, os.X_OK),
    }

    ended = _now()
    _audit(ws.get("id"), "succeeded", path=abs_path, result_summary={"type": typ, "size": int(st.st_size)}, started_at=started, ended_at=ended)
    return info

def list_allowed_directories(workspace_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        import random
        for _ in range(16):
            out.append(alphabet[random.randrange(32)])
        return prefix + "".join(reversed(out))

    def _audit(op_row):
        ops = _load("fs_operations.json")
        ops.append(op_row)
        _save("fs_operations.json", ops)

    ulid_pat = re.compile(r"^dcm_wsp_[0-9A-HJKMNP-TV-Z]{26}$")

    workspaces = _load("workspaces.json")

    target = None
    if workspace_id is not None:
        if not isinstance(workspace_id, str):
            return _err("VALIDATION_ERROR", "workspace_id must be a string")
        if not ulid_pat.match(workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id must match ^dcm_wsp_[0-9A-HJKMNP-TV-Z]{26}$")
        for w in workspaces:
            if w.get("id") == workspace_id:
                target = w
                break
        if target is None:
            return _err("NOT_FOUND", "Workspace not found")
        # Ambient auth: must be able to resolve this workspace for viewing; require active/suspended (not deleted).
        if target.get("status") == "deleted":
            return _err("UNAUTHORIZED", "Not authorized to view allowlist for deleted workspace")
    else:
        # Server effective allowlist: pick an active workspace that can serve calls; if none, empty list.
        for w in workspaces:
            if w.get("status") == "active" and isinstance(w.get("allowed_directories"), list):
                target = w
                break

    dirs = []
    ws_id = None
    if target is not None:
        ws_id = target.get("id")
        ad = target.get("allowed_directories")
        if isinstance(ad, list):
            dirs = [d for d in ad if isinstance(d, str)]
        else:
            dirs = []

    # Audit (supported by schema)
    op = {
        "id": _new_id("dcm_fso_"),
        "workspace_id": ws_id,
        "op_type": "list_allowed_directories",
        "status": "succeeded",
        "path": None,
        "paths": None,
        "destination": None,
        "pattern": None,
        "file_pattern": None,
        "ignore_case": None,
        "include_hidden": None,
        "context_lines": None,
        "max_results": None,
        "timeout_ms": None,
        "is_url": None,
        "block_content": None,
        "content_bytes_written": None,
        "result_summary": {"count": len(dirs), "workspace_id": ws_id},
        "error_message": None,
        "started_at": now,
        "ended_at": now,
        "created_at": now,
        "updated_at": now,
    }
    _audit(op)

    return {"workspace_id": ws_id, "allowed_directories": dirs}

def edit_block(blockContent, **_extra):
    import json, os, datetime, time, random, tempfile

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
