            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32]); ts //= 32
        for _ in range(16):
            out.append(alphabet[random.randrange(32)])
        return prefix + "".join(reversed(out))

    def _audit(workspace_id, status, **fields):
        ops = _load("fs_operations.json")
        if not isinstance(ops, list):
            ops = []
        now = _now()
        row = {
            "id": _new_id("dcm_fso_"),
            "workspace_id": workspace_id,
            "op_type": "edit_block",
            "status": status,
            "path": fields.get("path"),
            "paths": None,
            "destination": None,
            "pattern": None,
            "file_pattern": None,
            "ignore_case": None,
            "include_hidden": None,
            "context_lines": None,
            "max_results": None,
            "timeout_ms": None,
            "is_url": None,
            "block_content": fields.get("block_content"),
            "content_bytes_written": fields.get("content_bytes_written"),
            "result_summary": fields.get("result_summary"),
            "error_message": fields.get("error_message"),
            "started_at": fields.get("started_at"),
            "ended_at": fields.get("ended_at"),
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("fs_operations.json", ops)
        return row

    def _pick_workspace_for_path(abs_path):
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
        if not candidates:
            candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") in ("active", "suspended")]
        for w in candidates:
            allowed = w.get("allowed_directories")
            if not (isinstance(w.get("id"), str) and w.get("id")):
                continue
            if not (isinstance(allowed, list) and len(allowed) >= 1):
                continue
            for d in allowed:
                if not isinstance(d, str) or not d:
                    continue
                d_abs = os.path.abspath(os.path.normpath(d))
                try:
                    if os.path.commonpath([abs_path, d_abs]) == d_abs:
                        return w
                except Exception:
                    continue
        return None

    if not isinstance(blockContent, str) or not blockContent:
        return _err("VALIDATION_ERROR", "blockContent is required and must be a string.", field="blockContent")

    started = _now()

    # Accept JSON payload like {"path": "...", "startLine":1,"endLine":1,"replacement":"..."}
    target_path = None
    start_line = None
    end_line = None
    replacement = None

    parsed_json = None
    try:
        parsed_json = json.loads(blockContent)
    except Exception:
        parsed_json = None

    if isinstance(parsed_json, dict):
        target_path = parsed_json.get("path") or parsed_json.get("file") or parsed_json.get("filepath")
        start_line = parsed_json.get("startLine")
        end_line = parsed_json.get("endLine")
        replacement = parsed_json.get("replacement")
        if not isinstance(target_path, str) or not target_path.strip():
            return _err("VALIDATION_ERROR", "JSON blockContent must include a non-empty 'path'.", field="blockContent")
        if not isinstance(start_line, (int, float)) or isinstance(start_line, bool) or int(start_line) != start_line or int(start_line) < 1:
            return _err("VALIDATION_ERROR", "startLine must be an integer >= 1.", field="blockContent")
        if not isinstance(end_line, (int, float)) or isinstance(end_line, bool) or int(end_line) != end_line or int(end_line) < int(start_line):
            return _err("VALIDATION_ERROR", "endLine must be an integer >= startLine.", field="blockContent")
        if not isinstance(replacement, str):
            return _err("VALIDATION_ERROR", "replacement must be a string.", field="blockContent")
        start_line = int(start_line)
        end_line = int(end_line)
    else:
        # Basic SEARCH/REPLACE format:
        # FILE: /path
        # <<<<<<< SEARCH
        # ...
        # =======
        # ...
        # >>>>>>> REPLACE
        txt = blockContent
        lines = txt.splitlines()
        if lines and lines[0].startswith("FILE:"):
            target_path = lines[0][5:].strip()
            txt_body = "\n".join(lines[1:])
        else:
            txt_body = txt

        if "<<<<<<< SEARCH" not in txt_body or "=======" not in txt_body or ">>>>>>> REPLACE" not in txt_body:
            return _err("VALIDATION_ERROR", "blockContent must be JSON or include SEARCH/REPLACE markers.", field="blockContent")

        before, rest = txt_body.split("<<<<<<< SEARCH", 1)
        search_part, rest2 = rest.split("=======", 1)
        replace_part, _tail = rest2.split(">>>>>>> REPLACE", 1)
        search_text = search_part.strip("\n")
        replacement = replace_part.strip("\n")
        if not isinstance(target_path, str) or not target_path.strip():
            return _err("VALIDATION_ERROR", "SEARCH/REPLACE blockContent must include a leading 'FILE: /absolute/path' line.", field="blockContent")
        if search_text == "":
            return _err("VALIDATION_ERROR", "SEARCH block must be non-empty.", field="blockContent")
        # For SEARCH/REPLACE we apply first occurrence.
        start_line = None
        end_line = None

    abs_path = os.path.abspath(target_path)
    ws = _pick_workspace_for_path(abs_path)
    if not ws:
        workspaces = _load("workspaces.json")
        any_ws = None
        if isinstance(workspaces, list):
            for w in workspaces:
                if isinstance(w, dict) and w.get("status") in ("active", "suspended") and isinstance(w.get("id"), str):
                    any_ws = w
                    break
        if any_ws:
            _audit(any_ws.get("id"), "denied", path=abs_path, block_content=blockContent, error_message="Path is outside allowed directories.", started_at=started, ended_at=_now())
        return _err("CONFLICT", "Path is outside the allowlist.", path=abs_path)

    if not os.path.exists(abs_path):
        _audit(ws.get("id"), "failed", path=abs_path, block_content=blockContent, error_message="Not found.", started_at=started, ended_at=_now())
        return _err("NOT_FOUND", "File not found.", path=abs_path)
    if os.path.isdir(abs_path):
        _audit(ws.get("id"), "failed", path=abs_path, block_content=blockContent, error_message="Is a directory.", started_at=started, ended_at=_now())
        return _err("CONFLICT", "Path is a directory.", path=abs_path)

    try:
        with open(abs_path, "r", encoding="utf-8", errors="ignore") as f:
            orig = f.read()
    except Exception as e:
        _audit(ws.get("id"), "failed", path=abs_path, block_content=blockContent, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Failed to read file for editing.", error_message=str(e), path=abs_path)

    new_text = None
    if start_line is not None:
        orig_lines = orig.splitlines(True)  # keep ends
        if start_line > len(orig_lines):
            _audit(ws.get("id"), "failed", path=abs_path, block_content=blockContent, error_message="startLine out of range.", started_at=started, ended_at=_now())
            return _err("CONFLICT", "startLine is out of range for this file.", path=abs_path)
        if end_line > len(orig_lines):
            _audit(ws.get("id"), "failed", path=abs_path, block_content=blockContent, error_message="endLine out of range.", started_at=started, ended_at=_now())
            return _err("CONFLICT", "endLine is out of range for this file.", path=abs_path)

        before = "".join(orig_lines[:start_line - 1])
        after = "".join(orig_lines[end_line:])
        new_text = before + replacement + ("" if replacement.endswith("\n") or after.startswith("\n") or after == "" else "\n") + after
    else:
        # SEARCH/REPLACE: apply first occurrence of exact search block
        # We don't have search_text stored separately here; reconstruct from payload:
        txt_body = blockContent.split("\n", 1)[1] if blockContent.splitlines() and blockContent.splitlines()[0].startswith("FILE:") else blockContent
        _b, rest = txt_body.split("<<<<<<< SEARCH", 1)
        search_part, _rest2 = rest.split("=======", 1)
        search_text = search_part.strip("\n")
        idx = orig.find(search_text)
        if idx < 0:
            _audit(ws.get("id"), "failed", path=abs_path, block_content=blockContent, error_message="SEARCH block not found.", started_at=started, ended_at=_now())
            return _err("NOT_FOUND", "SEARCH block not found in file.", path=abs_path)
        new_text = orig[:idx] + replacement + orig[idx + len(search_text):]

    if new_text == orig:
        _audit(ws.get("id"), "succeeded", path=abs_path, block_content=blockContent, content_bytes_written=0, result_summary={"changed": False}, started_at=started, ended_at=_now())
        return {"path": abs_path, "changed": False, "content": orig}

    # Atomic write
    parent = os.path.dirname(abs_path) or abs_path
    tmp_path = None
    data = new_text.encode("utf-8")
    try:
        fd, tmp_path = tempfile.mkstemp(prefix=".dcm_edit_", dir=parent)
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, abs_path)
        tmp_path = None
    except Exception as e:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass
        _audit(ws.get("id"), "failed", path=abs_path, block_content=blockContent, error_message=str(e), started_at=started, ended_at=_now())
        return _err("CONFLICT", "Failed to apply edit.", error_message=str(e), path=abs_path)

    ended = _now()
    _audit(ws.get("id"), "succeeded", path=abs_path, block_content=blockContent, content_bytes_written=len(data), result_summary={"changed": True, "bytes": len(data)}, started_at=started, ended_at=ended)
    return {"path": abs_path, "changed": True, "content": new_text}

