        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()

    # Optional auditing supported by schema: use fs_operations with op_type=list_allowed_directories only when appropriate.
    # For identity endpoint, we avoid incorrect op_type; no dedicated audit collection exists, so we do not persist an audit row.
    # (Business rules emphasize observable dynamics when a usage/audit collection exists; here it does not for identity.)

    # Authentication: No credential store/schema provided. Treat api_key as optional ambient auth.
    # If api_key is provided, accept any non-empty string as "presented" and proceed; if empty string, validation error.
    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string")
    if isinstance(api_key, str) and api_key.strip() == "":
        return _err("VALIDATION_ERROR", "api_key must not be empty")

    workspaces = _load("workspaces.json")
    # Pick an active workspace context if available; otherwise none.
    active_ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("status") == "active":
            active_ws = w
            break

    # Service has no entitlement model in schema; therefore never FORBIDDEN.
    # Also, if no api_key presented, we still allow ambient auth per contract; thus never UNAUTHORIZED here.
    identity = {
        "subject": {
            "type": "api_key" if api_key else "runtime_default",
            "identifier": api_key if api_key else "default",
        },
        "scopes": ["desktop_commander:full"],
        "workspace": active_ws,
        "rate_limit": {
            "limited": False,
            "remaining": None,
            "reset_at": None,
        },
        "quota": {
            "limited": False,
            "remaining": None,
            "reset_at": None,
        },
        "timestamp": _now(),
        "latency_ms": int((time.time() - t0) * 1000),
    }
    return {"data": identity}

def list_workspaces(api_key=None, status=None, query=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate inputs
    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "suspended", "deleted"):
            return _err("VALIDATION_ERROR", "Unsupported status", allowed=["active", "suspended", "deleted"])
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit out of range (1..200)")
    else:
        limit = 50
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is not None:
        if not isinstance(sort, str):
            return _err("VALIDATION_ERROR", "sort must be a string")
        if sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"):
            return _err("VALIDATION_ERROR", "Unsupported sort", allowed=["created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"])
    else:
        sort = "created_at"

    # Auth: schema has no API key table; treat as ambient auth. Never FORBIDDEN based on missing schema.
    rows = _load("workspaces.json")
    if not isinstance(rows, list):
        return _err("FAILED", "Datastore corrupted")  # unexpected, but avoid raising

    # Filter
    out = []
    q = query.lower() if isinstance(query, str) else None
    for w in rows:
        if not isinstance(w, dict):
            continue
        if status is not None and w.get("status") != status:
            continue
        if q is not None:
            nm = w.get("name")
            if not isinstance(nm, str) or q not in nm.lower():
                continue
        out.append(w)

    # Sort
    reverse = False
    key = sort
    if sort.startswith("-"):
        reverse = True
        key = sort[1:]

    def _sort_key(w):
        v = w.get(key)
        if v is None:
            return ""
        return v

    out.sort(key=_sort_key, reverse=reverse)

    # Cursor: opaque base64 of integer offset
    start = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            start = int(decoded.decode("utf-8"))
            if start < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    total = len(out)
    page = out[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = base64.urlsafe_b64encode(str(start + limit).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": next_cursor is not None,
            "next_cursor": next_cursor,
            "sort": sort,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def create_workspace(
    name,
    allowed_directories,
    api_key=None,
    default_command_timeout_ms=None,
    default_search_timeout_ms=None,
    max_command_timeout_ms=None,
    max_search_timeout_ms=None,
    max_search_results=None,
    **_extra
):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32]); ts //= 32
        for _ in range(16):
            out.append(alphabet[random.randrange(32)])
        return prefix + "".join(reversed(out))

    # Ambient auth; if api_key provided validate type only (no credential store exists in this schema)
    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string.", field="api_key")

    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    nm = name.strip()
    if len(nm) > 200:
        return _err("VALIDATION_ERROR", "name must be at most 200 characters.", field="name")

    if not isinstance(allowed_directories, list) or len(allowed_directories) < 1:
        return _err("VALIDATION_ERROR", "allowed_directories must be a non-empty array of strings.", field="allowed_directories")

    norm_dirs = []
    for p in allowed_directories:
        if not isinstance(p, str) or not p.strip():
            return _err("VALIDATION_ERROR", "allowed_directories entries must be non-empty strings.", field="allowed_directories")
        if not os.path.isabs(p):
            return _err("VALIDATION_ERROR", "allowed_directories entries must be absolute paths.", path=p)
        norm_dirs.append(os.path.abspath(os.path.normpath(p)))

    def _chk_int(x, field, minv=1, maxv=None):
        if x is None:
            return None
        if not isinstance(x, int) or isinstance(x, bool):
            return _err("VALIDATION_ERROR", f"{field} must be an integer.", field=field)
        if x < minv:
            return _err("VALIDATION_ERROR", f"{field} must be >= {minv}.", field=field)
        if maxv is not None and x > maxv:
            return _err("VALIDATION_ERROR", f"{field} must be <= {maxv}.", field=field)
        return x

    default_command_timeout_ms = _chk_int(default_command_timeout_ms, "default_command_timeout_ms", 1)
    if isinstance(default_command_timeout_ms, dict) and "error" in default_command_timeout_ms:
        return default_command_timeout_ms
    default_search_timeout_ms = _chk_int(default_search_timeout_ms, "default_search_timeout_ms", 1)
    if isinstance(default_search_timeout_ms, dict) and "error" in default_search_timeout_ms:
        return default_search_timeout_ms
    max_command_timeout_ms = _chk_int(max_command_timeout_ms, "max_command_timeout_ms", 1)
    if isinstance(max_command_timeout_ms, dict) and "error" in max_command_timeout_ms:
        return max_command_timeout_ms
    max_search_timeout_ms = _chk_int(max_search_timeout_ms, "max_search_timeout_ms", 1)
    if isinstance(max_search_timeout_ms, dict) and "error" in max_search_timeout_ms:
        return max_search_timeout_ms
    max_search_results = _chk_int(max_search_results, "max_search_results", 1, 100000)
    if isinstance(max_search_results, dict) and "error" in max_search_results:
        return max_search_results

    # defaults if omitted
    if default_command_timeout_ms is None:
        default_command_timeout_ms = 30000
    if default_search_timeout_ms is None:
        default_search_timeout_ms = 30000
    if max_command_timeout_ms is None:
        max_command_timeout_ms = max(60000, default_command_timeout_ms)
    if max_search_timeout_ms is None:
        max_search_timeout_ms = max(60000, default_search_timeout_ms)
    if max_search_results is None:
        max_search_results = 10000

    if max_command_timeout_ms < default_command_timeout_ms:
        return _err("VALIDATION_ERROR", "max_command_timeout_ms must be >= default_command_timeout_ms.", field="max_command_timeout_ms")
    if max_search_timeout_ms < default_search_timeout_ms:
        return _err("VALIDATION_ERROR", "max_search_timeout_ms must be >= default_search_timeout_ms.", field="max_search_timeout_ms")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    # unique(name)
    for w in workspaces:
        if isinstance(w, dict) and (w.get("name") or "").strip() == nm and w.get("status") != "deleted":
            return _err("CONFLICT", "Workspace name already exists.", name=nm)

    now = _now()
    row = {
        "id": _new_id("dcm_wsp_"),
        "name": nm,
        "status": "active",
        "allowed_directories": norm_dirs,
        "default_command_timeout_ms": int(default_command_timeout_ms),
        "default_search_timeout_ms": int(default_search_timeout_ms),
        "max_command_timeout_ms": int(max_command_timeout_ms),
        "max_search_timeout_ms": int(max_search_timeout_ms),
        "max_search_results": int(max_search_results),
        "created_at": now,
        "updated_at": now,
    }
    workspaces.append(row)
    _save("workspaces.json", workspaces)
    return {"workspace": row}

def update_workspace(
    id,
    api_key=None,
    name=None,
    status=None,
    allowed_directories=None,
    default_command_timeout_ms=None,
    default_search_timeout_ms=None,
    max_command_timeout_ms=None,
    max_search_timeout_ms=None,
    max_search_results=None,
    **_extra
):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_abs_dir(p):
        if not isinstance(p, str) or p.strip() == "":
            return False
        if not os.path.isabs(p):
            return False
        norm = os.path.normpath(p)
        return os.path.isabs(norm)

    t0 = time.time()

    # Validate
    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string")

    if not isinstance(id, str):
        return _err("VALIDATION_ERROR", "id must be a string")
    if not re.match(r"^dcm_wsp_[0-9A-HJKMNP-TV-Z]{26}$", id):
        return _err("VALIDATION_ERROR", "id must match ^dcm_wsp_[0-9A-HJKMNP-TV-Z]{26}$")

    if name is not None:
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "name must be a string")
        nm = name.strip()
        if len(nm) < 1 or len(nm) > 200:
            return _err("VALIDATION_ERROR", "name length must be 1..200")
    else:
        nm = None

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "suspended", "deleted"):
            return _err("VALIDATION_ERROR", "Unsupported status", allowed=["active", "suspended", "deleted"])

    if allowed_directories is not None:
        if not isinstance(allowed_directories, list) or len(allowed_directories) < 1:
            return _err("VALIDATION_ERROR", "allowed_directories must be a non-empty array of strings")
        norm_dirs = []
        for p in allowed_directories:
            if not _is_abs_dir(p):
                return _err("VALIDATION_ERROR", "allowed_directories must contain absolute paths", path=p)
            norm_dirs.append(os.path.normpath(p))
    else:
        norm_dirs = None

    def _chk_int(x, field, minv=1, maxv=None):
        if x is None:
            return None
        if not isinstance(x, int):
            return _err("VALIDATION_ERROR", f"{field} must be an integer")
        if x < minv:
            return _err("VALIDATION_ERROR", f"{field} must be >= {minv}")
        if maxv is not None and x > maxv:
            return _err("VALIDATION_ERROR", f"{field} must be <= {maxv}")
        return x

    dct = _chk_int(default_command_timeout_ms, "default_command_timeout_ms", 1)
    if isinstance(dct, dict) and "error" in dct:
        return dct
    dst = _chk_int(default_search_timeout_ms, "default_search_timeout_ms", 1)
    if isinstance(dst, dict) and "error" in dst:
        return dst
    mct = _chk_int(max_command_timeout_ms, "max_command_timeout_ms", 1)
    if isinstance(mct, dict) and "error" in mct:
        return mct
    mst = _chk_int(max_search_timeout_ms, "max_search_timeout_ms", 1)
    if isinstance(mst, dict) and "error" in mst:
        return mst
    msr = _chk_int(max_search_results, "max_search_results", 1, 100000)
    if isinstance(msr, dict) and "error" in msr:
        return msr

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        return _err("FAILED", "Datastore corrupted")

    idx = None
    for i, w in enumerate(workspaces):
        if isinstance(w, dict) and w.get("id") == id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Workspace not found", id=id)

    ws = workspaces[idx]

    # Unique(name)
    if nm is not None and nm != ws.get("name"):
        for w in workspaces:
            if isinstance(w, dict) and w.get("name") == nm and w.get("id") != id:
                return _err("CONFLICT", "Workspace name already exists", field="name")

    # Lifecycle transition validation
    if status is not None and status != ws.get("status"):
        cur = ws.get("status")
        transitions = {
            "active": ["suspended", "deleted"],
            "suspended": ["active", "deleted"],
            "deleted": [],
        }
        allowed = transitions.get(cur, [])
        if status not in allowed:
            # Tool description says CONFLICT for invalid transition
            return _err("CONFLICT", "Requested status transition is not allowed", from_status=cur, to_status=status)

    # Prepare updated values, enforcing cross-field constraints using resulting values
    new_ws = dict(ws)

    if nm is not None:
        new_ws["name"] = nm
    if status is not None:
        new_ws["status"] = status
    if norm_dirs is not None:
        new_ws["allowed_directories"] = norm_dirs
    if dct is not None:
        new_ws["default_command_timeout_ms"] = dct
    if dst is not None:
        new_ws["default_search_timeout_ms"] = dst
    if mct is not None:
        new_ws["max_command_timeout_ms"] = mct
    if mst is not None:
        new_ws["max_search_timeout_ms"] = mst
    if msr is not None:
        new_ws["max_search_results"] = msr

    # Enforce constraints after merge
    if not isinstance(new_ws.get("allowed_directories"), list) or len(new_ws["allowed_directories"]) < 1:
        return _err("VALIDATION_ERROR", "allowed_directories must have at least 1 entry")

    if not isinstance(new_ws.get("default_command_timeout_ms"), int) or new_ws["default_command_timeout_ms"] < 1:
        return _err("VALIDATION_ERROR", "default_command_timeout_ms must be >= 1")
    if not isinstance(new_ws.get("default_search_timeout_ms"), int) or new_ws["default_search_timeout_ms"] < 1:
        return _err("VALIDATION_ERROR", "default_search_timeout_ms must be >= 1")
    if not isinstance(new_ws.get("max_command_timeout_ms"), int) or new_ws["max_command_timeout_ms"] < 1:
        return _err("VALIDATION_ERROR", "max_command_timeout_ms must be >= 1")
    if not isinstance(new_ws.get("max_search_timeout_ms"), int) or new_ws["max_search_timeout_ms"] < 1:
        return _err("VALIDATION_ERROR", "max_search_timeout_ms must be >= 1")
    if not isinstance(new_ws.get("max_search_results"), int) or new_ws["max_search_results"] < 1:
        return _err("VALIDATION_ERROR", "max_search_results must be >= 1")

    if new_ws["max_command_timeout_ms"] < new_ws["default_command_timeout_ms"]:
        return _err("VALIDATION_ERROR", "max_command_timeout_ms must be >= default_command_timeout_ms")
    if new_ws["max_search_timeout_ms"] < new_ws["default_search_timeout_ms"]:
        return _err("VALIDATION_ERROR", "max_search_timeout_ms must be >= default_search_timeout_ms")

    new_ws["updated_at"] = _now()

    # No success without effect: ensure at least one field changes
    changed = False
    for k, v in new_ws.items():
        if ws.get(k) != v:
            changed = True
            break
    if not changed:
        return _err("CONFLICT", "No changes requested")

    workspaces[idx] = new_ws
    _save("workspaces.json", workspaces)

    return {
        "data": new_ws,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def list_fs_operations(api_key=None, workspace_id=None, op_type=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0060000" if __import__("os").path.isdir("./environment_mix/0060000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(float(v))
            except Exception:
                return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                # fromisoformat supports "YYYY-MM-DDTHH:MM:SS" and with fractions
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            dt = datetime.datetime.fromisoformat(s)
            # If it has tzinfo, normalize to naive UTC
            if dt.tzinfo is not None:
                return dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _cursor_decode(cur):
        if not cur:
            return None
        if not isinstance(cur, str):
            return "INVALID"
        try:
            padded = cur + "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return "INVALID"
            # expect {"i": <int>}
            i = obj.get("i")
            if not isinstance(i, int) or i < 0:
                return "INVALID"
            return i
        except Exception:
            return "INVALID"

    def _cursor_encode(i):
        raw = json.dumps({"i": int(i)}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()

    # Validate inputs
    ulid_pat = re.compile(r"^dcm_wsp_[0-9A-HJKMNP-TV-Z]{26}$")
    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string")
    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not ulid_pat.match(workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id must match ^dcm_wsp_[0-9A-HJKMNP-TV-Z]{26}$")
    allowed_op_types = {
        "read_file",
        "read_multiple_files",
        "write_file",
        "edit_block",
        "move_file",
        "search_files",
        "search_code",
        "get_file_info",
        "list_directory",
        "list_allowed_directories",
    }
    if op_type is not None:
        if not isinstance(op_type, str) or op_type not in allowed_op_types:
            return _err("VALIDATION_ERROR", "Invalid op_type", allowed=sorted(list(allowed_op_types)))
    allowed_status = {"queued", "running", "succeeded", "failed", "denied", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status", allowed=sorted(list(allowed_status)))
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    sort_allowed = {"created_at", "-created_at", "updated_at", "-updated_at", "started_at", "-started_at"}
    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in sort_allowed:
        return _err("VALIDATION_ERROR", "Invalid sort", allowed=sorted(list(sort_allowed)))

    # "Authentication is ambient": if api_key provided, validate only if we have a key store.
    # The schema provided has no api_keys collection, so we cannot verify explicit keys.
    # If a key store appears later, this can be extended.
    # FORBIDDEN behavior: no workspace ACL model exists; if a workspace_id is provided, ensure it exists.
    workspaces = _load("workspaces.json")
    wsp = None
    if workspace_id is not None:
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == workspace_id:
                wsp = w
                break
        if wsp is None:
            # Tool description says FORBIDDEN if not allowed, but we have no ACL data.
            # Prefer NOT_FOUND when workspace doesn't exist.
            return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
        if wsp.get("status") == "deleted":
            # Still allow audit visibility? Real systems vary; given "soft-delete remains for audit",
            # allow listing logs for deleted workspace. So no error here.
            pass

    ops = _load("fs_operations.json")

    # Filter rows
    filtered = []
    for r in ops:
        if not isinstance(r, dict):
            continue
        if workspace_id is not None and r.get("workspace_id") != workspace_id:
            continue
        if op_type is not None and r.get("op_type") != op_type:
            continue
        if status is not None and r.get("status") != status:
            continue
        filtered.append(r)

    # Sort
    desc = sort.startswith("-")
    sort_field = sort[1:] if desc else sort

    def _sort_key(r):
        dt = _parse_dt(r.get(sort_field))
        # None sorts last in descending? We'll normalize to epoch for stable ordering:
        # Use minimal for ascending, maximal for descending to push None to end consistently.
        if dt is None:
            return datetime.datetime.min if not desc else datetime.datetime.min
        return dt

    # Stable tie-breaker by id
    def _tie_id(r):
        v = r.get("id")
        return v if isinstance(v, str) else ""

    filtered.sort(key=lambda r: (_sort_key(r), _tie_id(r)), reverse=desc)

    # Pagination by index cursor
    start_i = 0
    decoded = _cursor_decode(cursor)
    if decoded == "INVALID":
        return _err("VALIDATION_ERROR", "Invalid cursor")
    if isinstance(decoded, int):
        start_i = decoded
        if start_i > len(filtered):
            start_i = len(filtered)

    page = filtered[start_i : start_i + limit]
    next_i = start_i + len(page)
    has_more = next_i < len(filtered)
    next_cursor = _cursor_encode(next_i) if has_more else None

    # Audit every call: schema lacks a generic request log for this endpoint.
    # We record this listing call into fs_operations as an audit entry using op_type='list_allowed_directories'
    # is not appropriate; therefore we do not create a fs_operations row here.
    # (If a request log collection existed, we'd write there.)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "object": "list",
        "data": page,
        "total": len(filtered),
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "filters": {"workspace_id": workspace_id, "op_type": op_type, "status": status},
        "meta": {"latency_ms": latency_ms, "timestamp": _now_iso()},
    }
